#define PI float(3.1415926535897932384626433)
#define PI2 (PI * 2.0)

vec3 palette(in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d)
{
    return a + b*cos( 6.283185*(c*t+d) );
}

vec3 ringGradient(float t)
{
    vec3 a = vec3(0.700, 0.700, -3.142);
    vec3 b = vec3(0.500, 0.500, -3.142);
    vec3 c = vec3(0.500, 0.500, -3.142);
    vec3 d = vec3(0.600, -0.107, -3.142);
    return palette(t, a, b, c, d);
}

float antiAliasDist(vec2 uv, float d) 
{
    float dxy = length(fwidth(uv));
    return smoothstep(-dxy, dxy, -d);
}

float drawRing(vec2 p) 
{
    float d = length(p) - 0.9;
    d = abs(d) - 0.1;
    return antiAliasDist(p, -d);
}

float angle(vec2 p)
{
    if(length(p) == 0.0) 
    {
        return 0.0;
    }

    float a = acos(dot(vec2(0.0, 1.0), normalize(p)));
    if(p.x < 0.0) 
    {
        a = PI2 - a;
    }

    return a;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x = uv.x * (iResolution.x / iResolution.y);

    float uvAngle = angle(uv);
    float anim = iMouse.x / iResolution.x * PI2;

    fragColor = vec4(0.0);

    if(uvAngle < anim) 
    {
        vec4 col = vec4(ringGradient(1.0 - iMouse.x / iResolution.x), 1.0);
        fragColor = mix(col, fragColor, drawRing(uv));
    }
    else 
    {
        const vec4 col = vec4(0.886, 0.941, 0.831, 1.0);
        fragColor = mix(col, fragColor, drawRing(uv));
    }
}
